function AnnouncementsNewInner() {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const createRow = useMutation({
    mutationFn: (input: Input<"create">) => client.announcements.create(input),
    onSuccess: async row => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await navigate({ to: "/announcements/$id", params: { id: text(row.id) } });
    }
  });
  return (
    <Pane title="New announcement" actions={<Link to="/announcements" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>}>
      <AnnouncementsForm
        fields={ANNOUNCEMENTS_CREATE}
        initial={EMPTY_ANNOUNCEMENTS}
        submitLabel="Create"
        pending={createRow.isPending}
        error={createRow.error}
        onSubmit={values => createRow.mutate(toAnnouncementsCreateInput(values))}
      />
    </Pane>
  );
}

function AnnouncementsDetailInner() {
  const { id: rawId } = useParams({ from: "/announcements/$id" });
  const id = idOf(rawId);
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState(false);
  const [openAction, setOpenAction] = useState<string | null>(null);
  useEffect(() => {
    setEditing(false);
    setOpenAction(null);
  }, [id]);
  const query = useQuery({ queryKey: [...KEY, "get", id], queryFn: () => client.announcements.get({ id }) });
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const updateRow = useMutation({
    mutationFn: (input: Inputs["announcements"]["update"]) => client.announcements.update(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      setEditing(false);
    }
  });
  const removeRow = useMutation({
    mutationFn: (input: Inputs["announcements"]["delete"]) => client.announcements.delete(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await navigate({ to: "/announcements" });
    }
  });
  const publishAction = useMutation({
    mutationFn: (input: Inputs["announcements"]["publish"]) => client.announcements.publish(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  if (query.isPending) return <PaneSkeleton />;
  if (query.error) return <ErrorNote error={query.error} className="m-6" />;
  const row: Detail = query.data;
  return (
    <Pane
      title={text(row.title) || "Announcement " + text(row.id)}
      actions={
        <>
          <Link to="/announcements" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>
          {canPublish(user, row) ? (
            <Button variant="outline" size="sm" disabled={publishAction.isPending} onClick={() => publishAction.mutate({ id })}>
              Publish
            </Button>
          ) : null}
          {canUpdate(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setEditing(current => !current)}>
              {editing ? "Cancel" : "Edit"}
            </Button>
          ) : null}
          {canDelete(user, row) ? (
            <Button
              variant="destructive"
              size="sm"
              disabled={removeRow.isPending}
              onClick={() => {
                if (window.confirm("Delete this announcement?")) removeRow.mutate({ id });
              }}
            >
              Delete
            </Button>
          ) : null}
        </>
      }
    >

      <ErrorNote error={publishAction.error} className="mb-4" />
      {editing ? (
        <AnnouncementsForm
          fields={ANNOUNCEMENTS_UPDATE}
          initial={announcementsFromRow(row)}
          submitLabel="Save"
          pending={updateRow.isPending}
          error={updateRow.error}
          onCancel={() => setEditing(false)}
          onSubmit={values => updateRow.mutate({ id, data: toAnnouncementsUpdateInput(values) })}
        />
      ) : (
        <dl className="grid gap-3">
        <FieldRow label="Title">{text(row.title) || "—"}</FieldRow>
        <FieldRow label="Body">
          <p className="whitespace-pre-wrap">{text(row.body) || "—"}</p>
        </FieldRow>
        <FieldRow label="Published">{row.published == null ? "—" : <Badge variant={row.published ? "default" : "outline"}>{yesNo(row.published)}</Badge>}</FieldRow>
        <FieldRow label="Author">{(row.author ? text(row.author.name) : text(row.author_id)) || "—"}</FieldRow>
        <FieldRow label="Created At">{formatDateTime(row.created_at) || "—"}</FieldRow>
        </dl>
      )}
    </Pane>
  );
}

